import { useState, useEffect, useRef } from "react";
import { useNavigate, useSearchParams } from "react-router-dom";
import {
  Store as StoreIcon, ClipboardList, Camera, Sparkles, Check,
  ScanText, FileSearch, Image as ImageIcon, GitCompare, ShieldAlert, ArrowRight,
  Loader2, AlertCircle, CheckCircle2, X, Zap, Brain, Cpu, Trash2,
  Star, RefreshCw, Maximize2, Clock, Target,
} from "lucide-react";
import { Card, PageHeader, Button, Modal } from "@/components/ui";
import { templates } from "@/mock";
import { getPhotoUrl } from "@/mock/photo";
import { useAllStores } from "@/lib/data";
import { useStore } from "@/store/useStore";
import { cn } from "@/lib/utils";
import type { Evidence, TemplateItem } from "@/types";

type Phase = "form" | "analyzing" | "done";
const AI_STEPS = [
  { name: "OCR 文字识别", desc: "识别标签、台账上的文字信息", icon: ScanText },
  { name: "信息提取", desc: "提取生产日期、保质期等结构化字段", icon: FileSearch },
  { name: "场景分类", desc: "判断每张照片所属区域", icon: ImageIcon },
  { name: "标准比对", desc: "对照巡检模板标准逐项检查", icon: GitCompare },
  { name: "风险判定", desc: "生成风险清单，标注等级和置信度", icon: ShieldAlert },
];

// 根据模板类型计算风险数量
const RISK_COUNT_MAP: Record<string, { high: number; mid: number; low: number }> = {
  daily: { high: 1, mid: 1, low: 1 },
  standard: { high: 2, mid: 2, low: 1 },
  special: { high: 1, mid: 1, low: 1 },
};

export default function InspectionNew() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const addInspection = useStore((s) => s.addInspection);
  const allStores = useAllStores();
  const [phase, setPhase] = useState<Phase>("form");
  // 从 URL 参数读取门店和模板 ID
  const initialStoreId = searchParams.get("storeId") || allStores[0]?.id || "";
  const initialTemplateId = searchParams.get("templateId") || "tpl-002";
  const [storeId, setStoreId] = useState(initialStoreId);
  const [templateId, setTemplateId] = useState(initialTemplateId);
  const [step, setStep] = useState(-1);
  // evidences 是真实的取证实体列表，每次点击"取证"生成一条
  const [evidences, setEvidences] = useState<Evidence[]>([]);
  const [newInspectionId, setNewInspectionId] = useState<string>("");
  const timersRef = useRef<ReturnType<typeof setTimeout>[]>([]);
  const evidencesRef = useRef(evidences);
  evidencesRef.current = evidences;
  // 大图预览状态
  const [previewEvidence, setPreviewEvidence] = useState<Evidence | null>(null);

  const template = templates.find((t) => t.id === templateId) || templates[0];
  const riskInfo = RISK_COUNT_MAP[template.type] || RISK_COUNT_MAP.standard;
  const totalRisks = riskInfo.high + riskInfo.mid + riskInfo.low;
  // 展示用模板检查项（取前 6 项，保持界面紧凑）
  const displayItems = template.items.slice(0, 6);
  const score = Math.max(40, 100 - riskInfo.high * 15 - riskInfo.mid * 8 - riskInfo.low * 3);
  const selectedStoreName = allStores.find((s) => s.id === storeId)?.name || "未知门店";

  // 取证校验：每个必拍项的 evidence 数量 >= requiredPhotoCount
  const missingItems = displayItems
    .filter((item) => item.required)
    .map((item) => {
      const count = evidences.filter((e) => e.templateItemId === item.id).length;
      return { item, count, shortfall: Math.max(0, item.requiredPhotoCount - count) };
    })
    .filter((m) => m.shortfall > 0);
  const canStartAnalysis = missingItems.length === 0 && !!storeId;
  const totalRequiredPhotos = displayItems
    .filter((item) => item.required)
    .reduce((sum, item) => sum + item.requiredPhotoCount, 0);
  const totalCapturedPhotos = evidences.length;

  useEffect(() => {
    if (phase !== "analyzing") return;
    setStep(-1);
    const timers: ReturnType<typeof setTimeout>[] = [];
    timers.push(setTimeout(() => setStep(0), 200));
    for (let i = 0; i < 5; i++) {
      timers.push(setTimeout(() => setStep(i), 200 + (i + 1) * 700));
    }
    // 分析完成后生成真实巡检记录，传入用户实际拍摄的 evidences
    timers.push(setTimeout(() => {
      const id = addInspection({
        storeId,
        template,
        inspector: "张品控",
        evidences: evidencesRef.current,
      });
      setNewInspectionId(id);
      setPhase("done");
    }, 200 + 6 * 700));
    timersRef.current = timers;
    return () => timers.forEach((t) => clearTimeout(t));
  }, [phase, addInspection, storeId, template]);

  const handleStart = () => {
    if (!canStartAnalysis) return;
    setPhase("analyzing");
  };
  const handleViewResult = () => navigate(`/inspection/${newInspectionId}`);

  // 生成一条 Evidence（共用逻辑，addPhoto 和 retake 都用）
  const createEvidence = (item: TemplateItem, index: number): Evidence => {
    // 红框位置（确定性，基于已拍数量）
    const boxPatterns = [
      { x: 20, y: 30, w: 50, h: 25 },
      { x: 35, y: 20, w: 30, h: 20 },
      { x: 15, y: 40, w: 60, h: 35 },
      { x: 10, y: 25, w: 70, h: 30 },
      { x: 25, y: 35, w: 45, h: 40 },
      { x: 30, y: 15, w: 40, h: 30 },
    ];
    const aiResultTemplates: Record<string, string> = {
      食材标签: "OCR识别：生产日期2026-06-15，保质期至2026-07-05。判定：已过期3天。",
      冰箱温度: "识别温度值：7.2℃。标准要求0-4℃。超标3.2℃。",
      操作台: "场景识别：操作台。检测到生熟食材混放，台面有水渍污渍。",
      台账记录: "OCR识别：消毒记录缺失近3日数据，台账不连续。",
      垃圾桶: "场景识别：垃圾桶。检测到垃圾桶未加盖，周边有溢出物。",
      消毒柜: "场景识别：消毒柜。指示灯异常，疑似故障。",
      仓储: "场景识别：仓库。部分原料未离墙离地存放。",
      洗手池: "场景识别：洗手池。洗手液不足，干手器正常。",
      健康证: "OCR识别：2名员工健康证已过期，需重新办理。",
    };

    return {
      id: `ev-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      inspectionId: "", // 由 addInspection 填充
      templateItemId: item.id,
      category: item.category,
      url: getPhotoUrl(item.category),
      source: "demo",
      capturedAt: new Date().toISOString(),
      aiResult: aiResultTemplates[item.category] || aiResultTemplates["操作台"],
      confidence: 0.82 + index * 0.05,
      box: boxPatterns[index % boxPatterns.length],
    };
  };

  // 每次点击"取证"生成一条独立的 Evidence 实体
  const addPhoto = (item: TemplateItem) => {
    const existingCount = evidences.filter(
      (e) => e.templateItemId === item.id
    ).length;
    if (existingCount >= item.maxPhotoCount) return;
    const newEvidence = createEvidence(item, existingCount);
    setEvidences((prev) => [...prev, newEvidence]);
  };

  // 删除指定 Evidence
  const removeEvidence = (evidenceId: string) => {
    setEvidences((prev) => prev.filter((e) => e.id !== evidenceId));
  };

  // 重拍：替换指定 Evidence（保持 ID 位置不变，生成新内容）
  const retakePhoto = (evidenceId: string) => {
    setEvidences((prev) => {
      const target = prev.find((e) => e.id === evidenceId);
      if (!target) return prev;
      const item = template.items.find((it) => it.id === target.templateItemId);
      if (!item) return prev;
      // 用同检查项的索引生成新内容
      const itemEvidences = prev.filter((e) => e.templateItemId === target.templateItemId);
      const idx = itemEvidences.findIndex((e) => e.id === evidenceId);
      const fresh = createEvidence(item, idx >= 0 ? idx : 0);
      // 保持原 ID，替换其他字段
      return prev.map((e) =>
        e.id === evidenceId
          ? { ...fresh, id: evidenceId }
          : e
      );
    });
  };

  // 标记主照片：将指定 Evidence 移到同检查项的第一位
  // （store 生成风险时取每项第一张作为 primaryEvidenceId）
  const setPrimaryEvidence = (evidenceId: string) => {
    setEvidences((prev) => {
      const target = prev.find((e) => e.id === evidenceId);
      if (!target) return prev;
      const itemId = target.templateItemId;
      // 重排同项：目标放第一，其余保持原序
      const sameItem = prev.filter((e) => e.templateItemId === itemId);
      const reorderedSameItem = [
        target,
        ...sameItem.filter((e) => e.id !== evidenceId),
      ];
      // 按原数组顺序重建：遇到同项首次出现时插入重排后的同项，跳过其余同项
      const finalResult: Evidence[] = [];
      let sameInserted = false;
      for (const e of prev) {
        if (e.templateItemId === itemId) {
          if (!sameInserted) {
            finalResult.push(...reorderedSameItem);
            sameInserted = true;
          }
        } else {
          finalResult.push(e);
        }
      }
      if (!sameInserted) finalResult.push(...reorderedSameItem);
      return finalResult;
    });
  };

  // 判断某张 Evidence 是否是同检查项的主照片（第一张）
  const isPrimaryEvidence = (evidence: Evidence): boolean => {
    const sameItem = evidences.filter((e) => e.templateItemId === evidence.templateItemId);
    return sameItem.length > 0 && sameItem[0].id === evidence.id;
  };

  // ========== AI 分析动画 ==========
  if (phase === "analyzing" || phase === "done") {
    return (
      <div className="animate-fade-in max-w-3xl mx-auto">
        <Card className="p-10 relative overflow-hidden" glow>
          {/* 背景光效 */}
          <div className="absolute top-0 left-1/2 -translate-x-1/2 w-96 h-96 rounded-full bg-brand-500/10 blur-3xl pointer-events-none" />
          <div className="absolute -bottom-20 -right-20 w-80 h-80 rounded-full bg-cyan-500/10 blur-3xl pointer-events-none" />

          <div className="relative text-center mb-8">
            <div className="relative inline-flex mb-5">
              <div className="w-20 h-20 rounded-2xl bg-gradient-to-br from-brand-900 via-brand-700 to-cyan-600 flex items-center justify-center shadow-glow-brand">
                {phase === "done" ? (
                  <CheckCircle2 className="w-10 h-10 text-white" />
                ) : (
                  <Brain className="w-10 h-10 text-white animate-pulse" />
                )}
              </div>
              {phase === "analyzing" && (
                <span className="absolute -inset-2 rounded-3xl border-2 border-brand-400/40 animate-ping" />
              )}
            </div>
            <div className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-cyan-50 text-cyan-700 text-[10px] font-semibold tracking-widest uppercase mb-2">
              <Sparkles className="w-3 h-3" /> AI Vision Analysis
            </div>
            <h2 className="text-2xl font-bold text-ink-900 font-display tracking-tight">
              {phase === "done" ? "AI 分析完成" : "AI 正在分析"}
            </h2>
            <p className="text-sm text-ink-500 mt-1.5 font-light">
              {phase === "done"
                ? `已识别 ${totalRisks} 项风险，巡检得分 ${score} 分`
                : `正在分析 ${selectedStoreName} 的巡检照片`}
            </p>
          </div>

          {/* 步骤动画 */}
          <div className="space-y-3 mb-8">
            {AI_STEPS.map((s, i) => {
              const Icon = s.icon;
              const isDone = phase === "done" || i < step;
              const isActive = phase === "analyzing" && i === step;
              return (
                <div
                  key={i}
                  className={cn(
                    "relative flex items-center gap-4 p-4 rounded-xl border transition-all duration-500",
                    isDone ? "border-emerald-200 bg-gradient-to-r from-emerald-50/60 to-cyan-50/30" :
                    isActive ? "border-brand-300 bg-gradient-to-r from-brand-50 to-cyan-50/50 shadow-soft" :
                    "border-ink-200/40 bg-white/50"
                  )}
                >
                  {/* 步骤序号 */}
                  <div className={cn(
                    "w-10 h-10 rounded-xl flex items-center justify-center flex-shrink-0 transition-all",
                    isDone ? "bg-gradient-to-br from-emerald-500 to-emerald-600 shadow-[0_0_16px_rgba(16,185,129,0.4)]" :
                    isActive ? "bg-gradient-to-br from-brand-700 to-cyan-600 shadow-glow-brand" :
                    "bg-ink-100/60"
                  )}>
                    {isDone ? (
                      <Check className="w-5 h-5 text-white" />
                    ) : isActive ? (
                      <Loader2 className="w-5 h-5 text-white animate-spin" />
                    ) : (
                      <span className="text-sm font-bold text-ink-400 font-mono">{i + 1}</span>
                    )}
                  </div>
                  <div className="flex-1">
                    <div className="flex items-center gap-2">
                      <Icon className={cn("w-3.5 h-3.5", isDone ? "text-emerald-500" : isActive ? "text-brand-700" : "text-ink-300")} />
                      <p className={cn(
                        "text-sm font-semibold",
                        isDone ? "text-emerald-700" : isActive ? "text-brand-700" : "text-ink-400"
                      )}>
                        {s.name}
                      </p>
                    </div>
                    <p className="text-xs text-ink-400 mt-0.5">{s.desc}</p>
                  </div>
                  {isActive && (
                    <span className="text-[10px] text-brand-600 font-mono uppercase tracking-wider animate-pulse">Processing</span>
                  )}
                  {isDone && (
                    <span className="text-[10px] text-emerald-600 font-mono uppercase tracking-wider">Done</span>
                  )}
                </div>
              );
            })}
          </div>

          {/* 进度条 */}
          <div className="relative w-full h-1.5 bg-ink-100/60 rounded-full overflow-hidden mb-8">
            <div
              className="h-full bg-gradient-to-r from-brand-900 via-brand-600 to-cyan-500 rounded-full transition-all duration-700 ease-out"
              style={{ width: phase === "done" ? "100%" : `${((step + 1) / 5) * 100}%` }}
            >
              <div className="absolute inset-0 bg-white/30 shine-bar" />
            </div>
          </div>

          {/* 完成结果 */}
          {phase === "done" && (
            <div className="animate-fade-in-up">
              <div className="relative rounded-xl bg-gradient-to-br from-ink-50 to-white border border-ink-200/60 p-5 mb-6 overflow-hidden">
                <div className="absolute -top-10 -right-10 w-40 h-40 bg-gradient-to-br from-emerald-200/30 to-transparent rounded-full blur-2xl" />
                <h3 className="text-sm font-semibold text-ink-800 mb-4 flex items-center gap-2 relative">
                  <Zap className="w-4 h-4 text-amber-500" /> AI 识别结果摘要
                </h3>
                <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 relative">
                  {[
                    { label: "高风险", value: riskInfo.high, color: "from-red-500 to-red-600", text: "text-red-600" },
                    { label: "中风险", value: riskInfo.mid, color: "from-orange-500 to-orange-600", text: "text-orange-600" },
                    { label: "低风险", value: riskInfo.low, color: "from-amber-500 to-amber-600", text: "text-amber-600" },
                    { label: "已分析照片", value: totalCapturedPhotos, color: "from-brand-700 to-cyan-600", text: "text-brand-700" },
                  ].map((item) => (
                    <div key={item.label} className="relative bg-white rounded-lg p-3 text-center border border-ink-200/40 overflow-hidden">
                      <div className={cn("absolute top-0 left-0 right-0 h-0.5 bg-gradient-to-r", item.color)} />
                      <p className={cn("text-2xl font-bold font-display tabular-nums", item.text)}>{item.value}</p>
                      <p className="text-[10px] text-ink-500 mt-1">{item.label}</p>
                    </div>
                  ))}
                </div>
                <div className="mt-4 flex items-start gap-2 text-xs text-amber-700 bg-gradient-to-r from-amber-50 to-orange-50 rounded-md p-3 border border-amber-200/60">
                  <AlertCircle className="w-4 h-4 flex-shrink-0 mt-0.5" />
                  <span><strong className="font-semibold">AI 识别结果仅供参考</strong>，请人工复核确认后生成正式报告。</span>
                </div>
              </div>
              <Button variant="gradient" size="lg" className="w-full !h-12 !text-base" onClick={handleViewResult}>
                查看巡检详情 <ArrowRight className="w-4 h-4" />
              </Button>
            </div>
          )}
        </Card>
      </div>
    );
  }

  // ========== 表单 ==========
  return (
    <div className="animate-fade-in max-w-4xl mx-auto">
      <PageHeader
        title="新建巡检"
        subtitle="选择门店和模板，巡检取证后 AI 自动分析"
        badge={
          <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-cyan-50 text-cyan-700 text-[10px] font-semibold tracking-wider">
            <Sparkles className="w-3 h-3" /> AI POWERED
          </span>
        }
      />

      {/* 步骤1：选择门店 */}
      <StepCard step={1} title="选择门店">
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-2.5">
          {allStores.slice(0, 12).map((s) => (
            <button
              key={s.id}
              onClick={() => setStoreId(s.id)}
              className={cn(
                "group flex items-center gap-2.5 p-3 rounded-xl border text-left transition cursor-pointer",
                storeId === s.id
                  ? "border-brand-500 bg-gradient-to-br from-brand-50 to-cyan-50/50 ring-2 ring-brand-200 shadow-soft"
                  : "border-ink-200/60 hover:border-brand-300 hover:bg-ink-50/30"
              )}
            >
              <div className={cn(
                "w-9 h-9 rounded-lg flex items-center justify-center flex-shrink-0 transition",
                storeId === s.id ? "bg-gradient-to-br from-brand-700 to-cyan-600 text-white shadow-glow-brand" : "bg-ink-100/60 text-ink-400"
              )}>
                <StoreIcon className="w-4 h-4" />
              </div>
              <div className="flex-1 min-w-0">
                <p className={cn("text-sm truncate font-medium", storeId === s.id ? "text-brand-700" : "text-ink-700")}>
                  {s.name}
                </p>
                <p className="text-[11px] text-ink-400 font-mono">{s.code} · {s.region}</p>
              </div>
              {storeId === s.id && (
                <div className="w-5 h-5 rounded-full bg-gradient-to-br from-brand-700 to-cyan-600 flex items-center justify-center flex-shrink-0">
                  <Check className="w-3 h-3 text-white" />
                </div>
              )}
            </button>
          ))}
        </div>
        <p className="text-xs text-ink-500 mt-3 flex items-center gap-1.5">
          <span className="text-ink-400">已选择：</span>
          <span className="font-semibold text-ink-700">{selectedStoreName}</span>
        </p>
      </StepCard>

      {/* 步骤2：选择模板 */}
      <StepCard step={2} title="选择巡检模板">
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
          {templates.map((t) => (
            <button
              key={t.id}
              onClick={() => { setTemplateId(t.id); setEvidences([]); }}
              className={cn(
                "relative p-4 rounded-xl border text-left transition cursor-pointer overflow-hidden",
                templateId === t.id
                  ? "border-brand-500 bg-gradient-to-br from-brand-50 to-cyan-50/30 ring-2 ring-brand-200 shadow-soft"
                  : "border-ink-200/60 hover:border-brand-300 hover:bg-ink-50/30"
              )}
            >
              <div className={cn(
                "absolute top-0 left-0 right-0 h-1",
                t.type === "daily" ? "bg-gradient-to-r from-emerald-400 to-emerald-500" :
                t.type === "standard" ? "bg-gradient-to-r from-brand-500 to-cyan-500" :
                "bg-gradient-to-r from-red-500 to-orange-500"
              )} />
              <div className="flex items-center justify-between mb-2.5">
                <span className="text-xl">
                  {t.type === "daily" ? "🟢" : t.type === "standard" ? "🔵" : "🔴"}
                </span>
                {templateId === t.id && (
                  <div className="w-5 h-5 rounded-full bg-gradient-to-br from-brand-700 to-cyan-600 flex items-center justify-center">
                    <Check className="w-3 h-3 text-white" />
                  </div>
                )}
              </div>
              <p className={cn("text-sm font-semibold", templateId === t.id ? "text-brand-700" : "text-ink-800")}>
                {t.name}
              </p>
              <p className="text-[11px] text-ink-400 mt-0.5">{t.typeName}</p>
              <p className="text-[11px] text-ink-500 mt-1.5 flex items-center gap-1">
                <ClipboardList className="w-3 h-3" />
                {t.itemCount} 项检查
              </p>
            </button>
          ))}
        </div>
      </StepCard>

      {/* 步骤3：巡检取证 */}
      <StepCard step={3} title="巡检取证">
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2 mb-3">
          <p className="text-xs text-ink-500 flex items-center gap-1.5">
            <Camera className="w-3.5 h-3.5 flex-shrink-0" />
            已拍 {totalCapturedPhotos}/{totalRequiredPhotos} 张，完成全部必拍项后可启动分析
          </p>
          <span className="text-[10px] text-cyan-600 bg-cyan-50 px-2 py-0.5 rounded-full font-medium flex items-center gap-1 self-start sm:self-auto">
            <Sparkles className="w-3 h-3" /> 演示模式使用样本照片
          </span>
        </div>
        <div className="space-y-2.5">
          {displayItems.map((item, i) => {
            const itemEvidences = evidences.filter((e) => e.templateItemId === item.id);
            const count = itemEvidences.length;
            const isMet = count >= item.requiredPhotoCount;
            const isFull = count >= item.maxPhotoCount;
            return (
              <div key={item.id} className={cn(
                "flex flex-col sm:flex-row sm:items-center gap-3 sm:gap-4 p-3 rounded-xl border transition",
                isMet ? "border-brand-200 bg-brand-50/30" :
                count > 0 ? "border-amber-200 bg-amber-50/20" :
                "border-ink-200/40 bg-ink-50/30"
              )}>
                <div className="flex items-center gap-3 sm:gap-4 flex-1 min-w-0">
                <div className={cn(
                  "flex items-center justify-center w-7 h-7 rounded-lg text-[11px] font-mono font-bold flex-shrink-0",
                  isMet ? "bg-gradient-to-br from-brand-100 to-cyan-100 text-brand-600" :
                  "bg-gradient-to-br from-ink-100 to-ink-200 text-ink-500"
                )}>
                  {isMet ? <Check className="w-3.5 h-3.5" /> : String(i + 1).padStart(2, "0")}
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 flex-wrap">
                    <p className="text-sm text-ink-800 font-medium">{item.name}</p>
                    <span className="text-[9px] text-red-500 bg-red-50 px-1.5 py-0.5 rounded font-semibold">必拍</span>
                    <span className={cn(
                      "text-[10px] tabular-nums px-1.5 py-0.5 rounded font-medium",
                      isMet ? "text-emerald-600 bg-emerald-50" : "text-amber-600 bg-amber-50"
                    )}>
                      {count}/{item.requiredPhotoCount}张
                    </span>
                  </div>
                  <p className="text-[11px] text-ink-500 mt-0.5">{item.photoReq}</p>
                </div>
                </div>
                <div className="flex items-center gap-1.5 flex-wrap">
                  {count > 0 && (
                    <div className="flex gap-1">
                      {itemEvidences.map((ev) => {
                        const isPrimary = isPrimaryEvidence(ev);
                        return (
                          <div key={ev.id} className={cn(
                            "group/thumb relative w-12 h-12 rounded-md overflow-hidden border-2 transition-all cursor-pointer",
                            isPrimary ? "border-amber-400 shadow-[0_0_8px_rgba(251,191,36,0.4)]" : "border-brand-200"
                          )}>
                            <img src={ev.url} alt={ev.category} className="w-full h-full object-cover" />
                            {/* 主照片标记 */}
                            {isPrimary && (
                              <span className="absolute top-0 left-0 bg-amber-400 text-white text-[8px] font-bold px-1 py-0.5 rounded-br flex items-center gap-0.5">
                                <Star className="w-2 h-2 fill-white" />主
                              </span>
                            )}
                            {/* 来源标识 */}
                            <span className="absolute bottom-0 right-0 text-[7px] text-white bg-black/50 px-1 font-medium">
                              {ev.source === "demo" ? "样本" : ev.source === "upload" ? "上传" : "相机"}
                            </span>
                            {/* hover 操作工具栏 */}
                            <div className="absolute inset-0 bg-black/60 flex items-center justify-center gap-1 opacity-0 group-hover/thumb:opacity-100 transition-opacity">
                              <button
                                onClick={() => setPreviewEvidence(ev)}
                                className="w-5 h-5 rounded bg-white/20 hover:bg-white/30 flex items-center justify-center transition"
                                title="查看大图"
                              >
                                <Maximize2 className="w-3 h-3 text-white" />
                              </button>
                              {!isPrimary && (
                                <button
                                  onClick={() => setPrimaryEvidence(ev.id)}
                                  className="w-5 h-5 rounded bg-amber-500/80 hover:bg-amber-500 flex items-center justify-center transition"
                                  title="标记为主照片"
                                >
                                  <Star className="w-3 h-3 text-white" />
                                </button>
                              )}
                              <button
                                onClick={() => retakePhoto(ev.id)}
                                className="w-5 h-5 rounded bg-cyan-500/80 hover:bg-cyan-500 flex items-center justify-center transition"
                                title="重拍"
                              >
                                <RefreshCw className="w-3 h-3 text-white" />
                              </button>
                              <button
                                onClick={() => removeEvidence(ev.id)}
                                className="w-5 h-5 rounded bg-red-500/80 hover:bg-red-500 flex items-center justify-center transition"
                                title="删除"
                              >
                                <Trash2 className="w-3 h-3 text-white" />
                              </button>
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  )}
                  <Button
                    variant="secondary"
                    size="sm"
                    onClick={() => addPhoto(item)}
                    disabled={isFull}
                  >
                    <Camera className="w-3.5 h-3.5" />
                    {isFull ? "已满" : count > 0 ? "再拍" : "取证"}
                  </Button>
                </div>
              </div>
            );
          })}
        </div>
      </StepCard>

      {/* 提交按钮 */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3 mt-6">
        <Button variant="ghost" onClick={() => navigate("/inspection")}>
          <X className="w-4 h-4" /> 取消
        </Button>
        <div className="flex flex-col sm:flex-row sm:items-center gap-3">
          {!canStartAnalysis && missingItems.length > 0 && (
            <span className="text-xs text-amber-600 flex items-center gap-1.5 animate-fade-in">
              <AlertCircle className="w-3.5 h-3.5 flex-shrink-0" />
              <span>还需 {missingItems.reduce((s, m) => s + m.shortfall, 0)} 张照片（{missingItems.map((m) => `${m.item.name} ${m.count}/${m.item.requiredPhotoCount}`).join("、")}）</span>
            </span>
          )}
          <Button
            variant="gradient"
            size="lg"
            onClick={handleStart}
            disabled={!canStartAnalysis}
            className={cn("sm:!px-8 w-full sm:w-auto", !canStartAnalysis && "opacity-50 cursor-not-allowed")}
          >
            <Cpu className="w-4 h-4" /> 开始 AI 分析
            <ArrowRight className="w-4 h-4" />
          </Button>
        </div>
      </div>

      {/* 大图预览弹窗 */}
      <Modal
        open={!!previewEvidence}
        onClose={() => setPreviewEvidence(null)}
        title="取证照片预览"
        size="lg"
      >
        {previewEvidence && (
          <div className="space-y-4">
            <div className="relative rounded-xl overflow-hidden bg-ink-100" style={{ height: 400 }}>
              <img src={previewEvidence.url} alt={previewEvidence.category} className="w-full h-full object-cover" />
              {previewEvidence.box && (
                <div className="absolute inset-0 pointer-events-none">
                  <div
                    className="absolute border-[3px] border-red-500 rounded"
                    style={{
                      left: `${previewEvidence.box.x}%`,
                      top: `${previewEvidence.box.y}%`,
                      width: `${previewEvidence.box.w}%`,
                      height: `${previewEvidence.box.h}%`,
                      boxShadow: "0 0 0 9999px rgba(15, 23, 42, 0.35)",
                    }}
                  >
                    <span className="absolute -top-7 left-0 inline-flex items-center gap-1 bg-red-500 text-white text-[11px] font-semibold px-2 py-0.5 rounded shadow-glow-red">
                      <Target className="w-3 h-3" /> AI 标注
                    </span>
                  </div>
                </div>
              )}
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div className="rounded-lg bg-ink-50/60 border border-ink-200/40 p-3">
                <p className="text-[10px] text-ink-400 font-semibold tracking-wider uppercase mb-1">分类</p>
                <p className="text-sm text-ink-800 font-medium">{previewEvidence.category}</p>
              </div>
              <div className="rounded-lg bg-ink-50/60 border border-ink-200/40 p-3">
                <p className="text-[10px] text-ink-400 font-semibold tracking-wider uppercase mb-1">来源</p>
                <p className="text-sm text-ink-800 font-medium">
                  {previewEvidence.source === "demo" ? "演示样本" : previewEvidence.source === "upload" ? "上传照片" : "相机拍摄"}
                </p>
              </div>
            </div>
            <div className="rounded-lg bg-gradient-to-br from-brand-50/60 to-cyan-50/40 border border-brand-100/60 p-3.5">
              <p className="text-[10px] text-ink-400 font-semibold tracking-wider uppercase mb-1.5 flex items-center gap-1">
                <ScanText className="w-3 h-3" /> AI 识别结果
              </p>
              <p className="text-sm text-ink-700 leading-relaxed">{previewEvidence.aiResult}</p>
              <p className="text-[11px] text-ink-400 mt-2">置信度 {(previewEvidence.confidence * 100).toFixed(0)}%</p>
            </div>
            <div className="flex items-center justify-between text-[11px] text-ink-400">
              <span className="flex items-center gap-1">
                <Clock className="w-3 h-3" />
                拍摄时间：{previewEvidence.capturedAt.replace("T", " ").slice(0, 19)}
              </span>
              {isPrimaryEvidence(previewEvidence) && (
                <span className="flex items-center gap-1 text-amber-600 font-medium">
                  <Star className="w-3 h-3 fill-amber-500" /> 主照片
                </span>
              )}
            </div>
          </div>
        )}
      </Modal>
    </div>
  );
}

// 步骤卡组件
function StepCard({ step, title, children }: { step: number; title: string; children: React.ReactNode }) {
  return (
    <Card className="p-4 sm:p-6 mb-4 relative overflow-hidden">
      <div className="absolute top-0 left-0 right-0 h-px bg-gradient-to-r from-transparent via-brand-200 to-transparent" />
      <div className="flex items-center gap-3 mb-4">
        <div className="relative">
          <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-brand-900 to-brand-700 text-white flex items-center justify-center text-sm font-bold font-display shadow-glow-brand">
            {step}
          </div>
        </div>
        <h3 className="text-sm font-semibold text-ink-800 tracking-wide">{title}</h3>
      </div>
      {children}
    </Card>
  );
}
